  ('b320dfcc-de94-4eb1-8a23-a407115b99e7'::uuid, 'a0000000-0000-4000-8000-000000000201'::uuid, 'SC', 'medicaid_mco', '99341', 'covered', '{"answer":"South Carolina Medicaid pays 99341 at $36.38 (non-facility) and $36.38 (facility) on the Base Physicians Fee Schedule, effective 2024-07-01. Billed by a nurse practitioner or physician assistant, the PA/NP schedule pays $29.10 — 80% of the physician rate — which is the rate that applies to most home-based palliative visits. This is the state fee-for-service rate. A Medicaid managed care plan is expected to pay on this basis unless its own contract states otherwise, so treat it as the floor rather than as this plan''s published rate.","rate":36.38,"facilityRate":36.38,"npPaRate":29.1,"npPaPercentOfPhysician":80,"manuallyPriced":false,"rateBasis":"sc_medicaid_ffs_base_physicians_schedule","appliesToService":"procedure code listed on the SC Medicaid Base Physicians Fee Schedule","mappedFrom":"state fee-for-service schedule applied as the managed care floor","sourceDocument":"SC DHHS — Base Physicians Fee Schedule (schedule creation date 5/15/2026)","supportingQuotes":[{"label":"PA/NP differential","document":"SC DHHS — Physician Assistant / Nurse Practitioner Fee Schedule (schedule creation date 8/15/2025)","quote":"SC DHHS Physician Assistant/Nurse Practitioner Fee Schedule (schedule creation date 8/15/2025), row: PROC 99341 | MOD 0 | PAYMENT RATE 29.1 | FACILITY RATE 29.1 | EFFECTIVE DATE 2024-07-01"}]}'::jsonb, 'covered', 0.85, DATE '2024-07-01', NULL, 'e5c1a7b2-0001-4d3a-9f10-2b6c8e4a1101'::uuid, 'SC DHHS Base Physicians Fee Schedule (schedule creation date 5/15/2026), row: PROC 99341 | MOD 0 | PAYMENT RATE 36.380000000000003 | FACILITY RATE 36.380000000000003 | EFFECTIVE DATE 2024-07-01', 'extract:sc-fee-schedule-2026-08'),
