  ('74e547f8-0431-4c09-815e-ca253bc1e234'::uuid, 'a0000000-0000-4000-8000-000000000201'::uuid, 'SC', 'medicaid_mco', '99348', 'covered', '{"answer":"South Carolina Medicaid pays 99348 at $56.31 (non-facility) and $56.31 (facility) on the Base Physicians Fee Schedule, effective 2024-07-01. Billed by a nurse practitioner or physician assistant, the PA/NP schedule pays $45.05 — 80% of the physician rate — which is the rate that applies to most home-based palliative visits. This is the state fee-for-service rate. A Medicaid managed care plan is expected to pay on this basis unless its own contract states otherwise, so treat it as the floor rather than as this plan''s published rate.","rate":56.31,"facilityRate":56.31,"npPaRate":45.05,"npPaPercentOfPhysician":80,"manuallyPriced":false,"rateBasis":"sc_medicaid_ffs_base_physicians_schedule","appliesToService":"procedure code listed on the SC Medicaid Base Physicians Fee Schedule","mappedFrom":"state fee-for-service schedule applied as the managed care floor","sourceDocument":"SC DHHS — Base Physicians Fee Schedule (schedule creation date 5/15/2026)","supportingQuotes":[{"label":"PA/NP differential","document":"SC DHHS — Physician Assistant / Nurse Practitioner Fee Schedule (schedule creation date 8/15/2025)","quote":"SC DHHS Physician Assistant/Nurse Practitioner Fee Schedule (schedule creation date 8/15/2025), row: PROC 99348 | MOD 0 | PAYMENT RATE 45.05 | FACILITY RATE 45.05 | EFFECTIVE DATE 2024-07-01"}]}'::jsonb, 'covered', 0.85, DATE '2024-07-01', NULL, 'e5c1a7b2-0001-4d3a-9f10-2b6c8e4a1101'::uuid, 'SC DHHS Base Physicians Fee Schedule (schedule creation date 5/15/2026), row: PROC 99348 | MOD 0 | PAYMENT RATE 56.31 | FACILITY RATE 56.31 | EFFECTIVE DATE 2024-07-01', 'extract:sc-fee-schedule-2026-08'),
